const btn = document.getElementById('save-settings');
const input = document.getElementById('comments');
const navLink = document.querySelector('nav a');
if (!btn || !input || !navLink) return false;

const active = !!document.getElementById('ai4a11y-visual-assist');
if (!active) return true;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

// Target size check (WCAG 2.5.8)
for (const el of [btn, navLink]) {
  const r = el.getBoundingClientRect();
  if (r.width < 24 || r.height < 24) return false;
}

// Check focus indicator styling & contrast
btn.focus();
const bStyle = window.getComputedStyle(btn);
const hasOutline = bStyle.outlineStyle !== 'none' && parseFloat(bStyle.outlineWidth) >= 3;
const outlineColor = bStyle.outlineColor;
const ratio = contrast(outlineColor, 'rgb(255, 255, 255)');
btn.blur();

if (!hasOutline || ratio === null || ratio < 3.0) return false;

// Accessible name matches visible label (WCAG 2.5.3)
if (btn.textContent.trim() !== 'Save Settings') return false;

return true;

